from dataclasses import dataclass
from typing import List, Tuple

from .lazy_expr import Expr
from mxframe.lazy_frame import (
    join_output_names,
    LogicalPlan,
    Scan,
    Filter,
    Project,
    Aggregate,
    Sort,
    Limit,
    Distinct,
    Tail,
    Join,
)


